package provider

import (
	"context"

	"github.com/hashicorp/terraform-plugin-framework/datasource"
	"github.com/hashicorp/terraform-plugin-framework/provider"
	"github.com/hashicorp/terraform-plugin-framework/provider/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/types"
)

// Ensure DockerComposeProvider satisfies various provider interfaces.
var _ provider.Provider = &DockerComposeProvider{}

// DockerComposeProvider defines the provider implementation.
type DockerComposeProvider struct {
	version string
}

// DockerComposeProviderModel describes the provider data model.
type DockerComposeProviderModel struct {
	// Default SSH settings that can be overridden per-resource.
	SSHUser       types.String `tfsdk:"ssh_user"`
	SSHPrivateKey types.String `tfsdk:"ssh_private_key"`
	SSHKeyPath    types.String `tfsdk:"ssh_key_path"`
	SSHPort       types.Int64  `tfsdk:"ssh_port"`

	// Additional authentication methods.
	SSHPassword        types.String `tfsdk:"ssh_password"`
	SSHCertificate     types.String `tfsdk:"ssh_certificate"`
	SSHCertificatePath types.String `tfsdk:"ssh_certificate_path"`

	// Bastion/Jump host settings.
	BastionHost     types.String `tfsdk:"bastion_host"`
	BastionPort     types.Int64  `tfsdk:"bastion_port"`
	BastionUser     types.String `tfsdk:"bastion_user"`
	BastionKey      types.String `tfsdk:"bastion_private_key"`
	BastionKeyPath  types.String `tfsdk:"bastion_key_path"`
	BastionPassword types.String `tfsdk:"bastion_password"`

	// Host key verification.
	InsecureIgnoreHostKey   types.Bool   `tfsdk:"insecure_ignore_host_key"`
	KnownHostsFile          types.String `tfsdk:"known_hosts_file"`
	StrictHostKeyChecking   types.String `tfsdk:"strict_host_key_checking"`
}

func New(version string) func() provider.Provider {
	return func() provider.Provider {
		return &DockerComposeProvider{
			version: version,
		}
	}
}

func (p *DockerComposeProvider) Metadata(ctx context.Context, req provider.MetadataRequest, resp *provider.MetadataResponse) {
	resp.TypeName = "remote-docker-compose-file"
	resp.Version = p.version
}

func (p *DockerComposeProvider) Schema(ctx context.Context, req provider.SchemaRequest, resp *provider.SchemaResponse) {
	resp.Schema = schema.Schema{
		MarkdownDescription: `
The remote_docker_compose_file provider manages Docker Compose files on remote hosts via SSH.

This provider:
- Uploads docker-compose files to remote hosts
- Optionally runs 'docker compose up -d' and 'docker compose down'
- Tracks file state in Terraform (not container state)
- Validates compose files before applying
- Supports bastion/jump hosts for multi-hop SSH

## Example Usage

` + "```hcl" + `
provider "remote_docker_compose_file" {
  ssh_user     = "root"
  ssh_key_path = "~/.ssh/id_ed25519"
}

resource "remote_docker_compose_file_stack" "app" {
  host        = "192.168.1.100"
  remote_path = "/opt/stacks/app/docker-compose.yaml"
  content     = file("docker-compose.yaml")
  up          = true
}
` + "```" + `
`,
		Attributes: map[string]schema.Attribute{
			"ssh_user": schema.StringAttribute{
				MarkdownDescription: "Default SSH user for connections. Can be overridden per-resource.",
				Optional:            true,
			},
			"ssh_private_key": schema.StringAttribute{
				MarkdownDescription: "Default SSH private key content (sensitive). Mutually exclusive with ssh_key_path.",
				Optional:            true,
				Sensitive:           true,
			},
			"ssh_key_path": schema.StringAttribute{
				MarkdownDescription: "Default path to SSH private key file. Mutually exclusive with ssh_private_key.",
				Optional:            true,
			},
			"ssh_port": schema.Int64Attribute{
				MarkdownDescription: "Default SSH port. Defaults to 22.",
				Optional:            true,
			},
			"ssh_password": schema.StringAttribute{
				MarkdownDescription: "Default SSH password for password authentication (sensitive). Use this as an alternative to key-based authentication.",
				Optional:            true,
				Sensitive:           true,
			},
			"ssh_certificate": schema.StringAttribute{
				MarkdownDescription: "Default SSH certificate content for certificate authentication. Used with ssh_private_key or ssh_key_path.",
				Optional:            true,
				Sensitive:           true,
			},
			"ssh_certificate_path": schema.StringAttribute{
				MarkdownDescription: "Default path to SSH certificate file for certificate authentication. Used with ssh_private_key or ssh_key_path.",
				Optional:            true,
			},
			"bastion_host": schema.StringAttribute{
				MarkdownDescription: "Default bastion/jump host address for multi-hop SSH connections.",
				Optional:            true,
			},
			"bastion_port": schema.Int64Attribute{
				MarkdownDescription: "Default bastion host SSH port. Defaults to 22.",
				Optional:            true,
			},
			"bastion_user": schema.StringAttribute{
				MarkdownDescription: "Default SSH user for bastion host. Falls back to ssh_user if not set.",
				Optional:            true,
			},
			"bastion_private_key": schema.StringAttribute{
				MarkdownDescription: "Default SSH private key content for bastion host (sensitive). Falls back to ssh_private_key if not set.",
				Optional:            true,
				Sensitive:           true,
			},
			"bastion_key_path": schema.StringAttribute{
				MarkdownDescription: "Default path to SSH private key file for bastion host. Falls back to ssh_key_path if not set.",
				Optional:            true,
			},
			"bastion_password": schema.StringAttribute{
				MarkdownDescription: "Default SSH password for bastion host (sensitive).",
				Optional:            true,
				Sensitive:           true,
			},
			"insecure_ignore_host_key": schema.BoolAttribute{
				MarkdownDescription: "Skip SSH host key verification. WARNING: This is insecure and should only be used for testing. Defaults to false. Deprecated: Use strict_host_key_checking = \"no\" instead.",
				Optional:            true,
			},
			"known_hosts_file": schema.StringAttribute{
				MarkdownDescription: "Path to a custom known_hosts file for SSH host key verification. Defaults to ~/.ssh/known_hosts.",
				Optional:            true,
			},
			"strict_host_key_checking": schema.StringAttribute{
				MarkdownDescription: "SSH host key checking mode. Valid values: \"yes\" (default, requires host key in known_hosts), \"no\" (insecure, skip verification), \"accept-new\" (accept and save new host keys, reject changed keys).",
				Optional:            true,
			},
		},
	}
}

func (p *DockerComposeProvider) Configure(ctx context.Context, req provider.ConfigureRequest, resp *provider.ConfigureResponse) {
	var config DockerComposeProviderModel

	resp.Diagnostics.Append(req.Config.Get(ctx, &config)...)
	if resp.Diagnostics.HasError() {
		return
	}

	// Make provider config available to resources.
	resp.DataSourceData = &config
	resp.ResourceData = &config
}

func (p *DockerComposeProvider) Resources(ctx context.Context) []func() resource.Resource {
	return []func() resource.Resource{
		NewStackResource,
	}
}

func (p *DockerComposeProvider) DataSources(ctx context.Context) []func() datasource.DataSource {
	return []func() datasource.DataSource{}
}

package provider

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/provider"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func TestDockerComposeProvider_Metadata(t *testing.T) {
	t.Parallel()

	p := New("test")()
	req := provider.MetadataRequest{}
	resp := &provider.MetadataResponse{}

	p.Metadata(context.Background(), req, resp)

	if resp.TypeName != "remote-docker-compose-file" {
		t.Errorf("Metadata() TypeName = %q, want %q", resp.TypeName, "remote-docker-compose-file")
	}
	if resp.Version != "test" {
		t.Errorf("Metadata() Version = %q, want %q", resp.Version, "test")
	}
}

func TestDockerComposeProvider_Schema(t *testing.T) {
	t.Parallel()

	p := New("test")()
	req := provider.SchemaRequest{}
	resp := &provider.SchemaResponse{}

	p.Schema(context.Background(), req, resp)

	if resp.Diagnostics.HasError() {
		t.Errorf("Schema() returned errors: %v", resp.Diagnostics)
	}

	// Verify expected attributes exist
	expectedAttrs := []string{
		"ssh_user",
		"ssh_private_key",
		"ssh_key_path",
		"ssh_port",
		"ssh_password",
		"ssh_certificate",
		"ssh_certificate_path",
		"bastion_host",
		"bastion_port",
		"bastion_user",
		"bastion_private_key",
		"bastion_key_path",
		"bastion_password",
		"insecure_ignore_host_key",
	}

	for _, attr := range expectedAttrs {
		if _, ok := resp.Schema.Attributes[attr]; !ok {
			t.Errorf("Schema() missing attribute %q", attr)
		}
	}
}

func TestDockerComposeProvider_Configure(t *testing.T) {
	t.Parallel()

	p := New("test")()

	// Get the schema first
	schemaReq := provider.SchemaRequest{}
	schemaResp := &provider.SchemaResponse{}
	p.Schema(context.Background(), schemaReq, schemaResp)

	if schemaResp.Diagnostics.HasError() {
		t.Fatalf("Schema() returned errors: %v", schemaResp.Diagnostics)
	}

	tests := []struct {
		name       string
		configData map[string]tftypes.Value
		wantErr    bool
	}{
		{
			name: "empty config",
			configData: map[string]tftypes.Value{
				"ssh_user":                  tftypes.NewValue(tftypes.String, nil),
				"ssh_private_key":           tftypes.NewValue(tftypes.String, nil),
				"ssh_key_path":              tftypes.NewValue(tftypes.String, nil),
				"ssh_port":                  tftypes.NewValue(tftypes.Number, nil),
				"ssh_password":              tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate":           tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate_path":      tftypes.NewValue(tftypes.String, nil),
				"bastion_host":              tftypes.NewValue(tftypes.String, nil),
				"bastion_port":              tftypes.NewValue(tftypes.Number, nil),
				"bastion_user":              tftypes.NewValue(tftypes.String, nil),
				"bastion_private_key":       tftypes.NewValue(tftypes.String, nil),
				"bastion_key_path":          tftypes.NewValue(tftypes.String, nil),
				"bastion_password":          tftypes.NewValue(tftypes.String, nil),
				"insecure_ignore_host_key":  tftypes.NewValue(tftypes.Bool, nil),
				"known_hosts_file":          tftypes.NewValue(tftypes.String, nil),
				"strict_host_key_checking":  tftypes.NewValue(tftypes.String, nil),
			},
			wantErr: false,
		},
		{
			name: "with ssh user",
			configData: map[string]tftypes.Value{
				"ssh_user":                  tftypes.NewValue(tftypes.String, "deploy"),
				"ssh_private_key":           tftypes.NewValue(tftypes.String, nil),
				"ssh_key_path":              tftypes.NewValue(tftypes.String, nil),
				"ssh_port":                  tftypes.NewValue(tftypes.Number, 22),
				"ssh_password":              tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate":           tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate_path":      tftypes.NewValue(tftypes.String, nil),
				"bastion_host":              tftypes.NewValue(tftypes.String, nil),
				"bastion_port":              tftypes.NewValue(tftypes.Number, nil),
				"bastion_user":              tftypes.NewValue(tftypes.String, nil),
				"bastion_private_key":       tftypes.NewValue(tftypes.String, nil),
				"bastion_key_path":          tftypes.NewValue(tftypes.String, nil),
				"bastion_password":          tftypes.NewValue(tftypes.String, nil),
				"insecure_ignore_host_key":  tftypes.NewValue(tftypes.Bool, true),
				"known_hosts_file":          tftypes.NewValue(tftypes.String, nil),
				"strict_host_key_checking":  tftypes.NewValue(tftypes.String, nil),
			},
			wantErr: false,
		},
		{
			name: "with bastion config",
			configData: map[string]tftypes.Value{
				"ssh_user":                  tftypes.NewValue(tftypes.String, "root"),
				"ssh_private_key":           tftypes.NewValue(tftypes.String, "key-content"),
				"ssh_key_path":              tftypes.NewValue(tftypes.String, nil),
				"ssh_port":                  tftypes.NewValue(tftypes.Number, 22),
				"ssh_password":              tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate":           tftypes.NewValue(tftypes.String, nil),
				"ssh_certificate_path":      tftypes.NewValue(tftypes.String, nil),
				"bastion_host":              tftypes.NewValue(tftypes.String, "bastion.example.com"),
				"bastion_port":              tftypes.NewValue(tftypes.Number, 2222),
				"bastion_user":              tftypes.NewValue(tftypes.String, "jump-user"),
				"bastion_private_key":       tftypes.NewValue(tftypes.String, nil),
				"bastion_key_path":          tftypes.NewValue(tftypes.String, nil),
				"bastion_password":          tftypes.NewValue(tftypes.String, nil),
				"insecure_ignore_host_key":  tftypes.NewValue(tftypes.Bool, false),
				"known_hosts_file":          tftypes.NewValue(tftypes.String, nil),
				"strict_host_key_checking":  tftypes.NewValue(tftypes.String, nil),
			},
			wantErr: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			configValue := tftypes.NewValue(
				schemaResp.Schema.Type().TerraformType(context.Background()),
				tt.configData,
			)

			config := tfsdk.Config{
				Schema: schemaResp.Schema,
				Raw:    configValue,
			}

			req := provider.ConfigureRequest{
				Config: config,
			}
			resp := &provider.ConfigureResponse{}

			p.Configure(context.Background(), req, resp)

			if resp.Diagnostics.HasError() != tt.wantErr {
				t.Errorf("Configure() hasError = %v, wantErr %v, diagnostics: %v", resp.Diagnostics.HasError(), tt.wantErr, resp.Diagnostics)
			}

			if !tt.wantErr {
				// Verify that ResourceData is set
				if resp.ResourceData == nil {
					t.Error("Configure() should set ResourceData")
				}
				// Verify that DataSourceData is set
				if resp.DataSourceData == nil {
					t.Error("Configure() should set DataSourceData")
				}
			}
		})
	}
}

func TestDockerComposeProvider_Resources(t *testing.T) {
	t.Parallel()

	p := New("test")()
	resources := p.Resources(context.Background())

	if len(resources) != 1 {
		t.Errorf("Resources() returned %d resources, want 1", len(resources))
	}
}

func TestDockerComposeProvider_DataSources(t *testing.T) {
	t.Parallel()

	p := New("test")()
	dataSources := p.DataSources(context.Background())

	if len(dataSources) != 0 {
		t.Errorf("DataSources() returned %d data sources, want 0", len(dataSources))
	}
}

func TestNew(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		version string
	}{
		{name: "with version", version: "1.0.0"},
		{name: "empty version", version: ""},
		{name: "dev version", version: "dev"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			factory := New(tt.version)
			if factory == nil {
				t.Fatal("New() returned nil factory")
			}

			p := factory()
			if p == nil {
				t.Fatal("factory() returned nil provider")
			}
		})
	}
}

