func TestNew(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name    string
		version string
	}{
		{name: "with version", version: "1.0.0"},
		{name: "empty version", version: ""},
		{name: "dev version", version: "dev"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()

			factory := New(tt.version)
